#include "vfs_layer_monitor.h"
#include <iostream>
#include <cstring>

// Include the generated bytecode header
#include "vfs_monitor_enhanced_bytecode.h"

namespace ebpf {

VFSLayerMonitor::~VFSLayerMonitor() {
    stop();
    detachKprobes();
    
    if (obj_) {
        bpf_object__close(obj_);
        obj_ = nullptr;
    }
}

bool VFSLayerMonitor::initialize() {
    std::cout << "VFS Layer Monitor: Initializing..." << std::endl;
    
    if (!loadVFSProgram()) {
        std::cerr << "VFS: Failed to load eBPF program" << std::endl;
        return false;
    }
    
    if (!attachKprobes()) {
        std::cerr << "VFS: Failed to attach kprobes" << std::endl;
        return false;
    }
    
    std::cout << "VFS Layer Monitor initialized successfully" << std::endl;
    return true;
}

bool VFSLayerMonitor::loadVFSProgram() {
    // Load the VFS enhanced eBPF program
    obj_ = bpf_object__open_mem(vfs_monitor_enhanced_o, 
                               vfs_monitor_enhanced_o_len, 
                               nullptr);
    if (!obj_) {
        std::cerr << "VFS: Failed to open VFS eBPF object" << std::endl;
        return false;
    }

    // Load the program into the kernel
    int ret = bpf_object__load(obj_);
    if (ret) {
        std::cerr << "VFS: Failed to load VFS eBPF object: " << ret << std::endl;
        bpf_object__close(obj_);
        obj_ = nullptr;
        return false;
    }

    std::cout << "VFS: eBPF program loaded successfully" << std::endl;
    return true;
}

bool VFSLayerMonitor::attachKprobes() {
    if (!obj_) {
        std::cerr << "VFS: No eBPF object to attach" << std::endl;
        return false;
    }

    // Define the kprobes we want to attach (VFS layer only, no syscall duplication)
    const char* kprobe_functions[] = {
        "vfs_create",
        "vfs_mkdir", 
        "vfs_unlink",
        "vfs_rmdir",
        "vfs_rename",
        "vfs_link",
        "vfs_symlink"
    };
    
    int attached_count = 0;
    int total_count = sizeof(kprobe_functions) / sizeof(kprobe_functions[0]);

    for (int i = 0; i < total_count; i++) {
        const char* func_name = kprobe_functions[i];
        
        // Find the program by name
        std::string prog_name = "trace_" + std::string(func_name);
        struct bpf_program *prog = bpf_object__find_program_by_name(obj_, prog_name.c_str());
        if (!prog) {
            std::cerr << "VFS: Warning - Program " << prog_name << " not found" << std::endl;
            continue;
        }

        // Attach kprobe
        struct bpf_link *link = bpf_program__attach_kprobe(prog, false, func_name);
        if (link) {
            kprobe_links_.push_back(link);
            attached_count++;
            std::cout << "VFS: Attached kprobe to " << func_name << std::endl;
        } else {
            std::cerr << "VFS: Warning - Failed to attach kprobe to " << func_name << std::endl;
        }
    }

    std::cout << "VFS: Attached " << attached_count << "/" << total_count << " kprobes" << std::endl;
    
    // Return true if we attached at least some kprobes
    return attached_count > 0;
}

void VFSLayerMonitor::detachKprobes() {
    for (auto* link : kprobe_links_) {
        if (link) {
            bpf_link__destroy(link);
        }
    }
    kprobe_links_.clear();
    std::cout << "VFS: All kprobes detached" << std::endl;
}

bool VFSLayerMonitor::start() {
    if (!obj_) {
        std::cerr << "VFS: No eBPF object loaded" << std::endl;
        return false;
    }

    // Get the ring buffer map (updated name)
    int ringbuf_fd = bpf_object__find_map_fd_by_name(obj_, "vfs_events");
    if (ringbuf_fd < 0) {
        std::cerr << "VFS: Failed to find vfs_events ring buffer map" << std::endl;
        return false;
    }

    // Create ring buffer
    ring_buf_ = ring_buffer__new(ringbuf_fd, handleRingBufferEvent, this, nullptr);
    if (!ring_buf_) {
        std::cerr << "VFS: Failed to create ring buffer" << std::endl;
        return false;
    }

    // Start polling thread
    is_running_ = true;
    polling_thread_ = std::thread(&VFSLayerMonitor::ringBufferPollLoop, this);
    
    std::cout << "VFS Layer Monitor started" << std::endl;
    std::cout << "VFS ring buffer polling started" << std::endl;
    return true;
}

void VFSLayerMonitor::stop() {
    if (is_running_) {
        is_running_ = false;
        
        if (polling_thread_.joinable()) {
            polling_thread_.join();
        }
        
        std::cout << "VFS ring buffer polling stopped" << std::endl;
    }
    
    if (ring_buf_) {
        ring_buffer__free(ring_buf_);
        ring_buf_ = nullptr;
    }
    
    std::cout << "VFS Layer Monitor stopped" << std::endl;
}

void VFSLayerMonitor::setEventHandler(std::function<void(const vfs_event&)> handler) {
    event_handler_ = handler;
}

void VFSLayerMonitor::ringBufferPollLoop() {
    while (is_running_) {
        int ret = ring_buffer__poll(ring_buf_, 100); // 100ms timeout
        if (ret < 0 && ret != -EINTR) {
            std::cerr << "VFS: Ring buffer polling error: " << ret << std::endl;
            break;
        }
    }
}

int VFSLayerMonitor::handleRingBufferEvent(void *ctx, void *data, size_t data_sz) {
    VFSLayerMonitor *monitor = static_cast<VFSLayerMonitor*>(ctx);
    
    // Accept VFS events - handle both possible sizes due to struct packing differences
    if (data_sz == 4120 || data_sz == sizeof(vfs_event)) {
        struct vfs_event *event = static_cast<struct vfs_event*>(data);
        
        // Debug output for VFS events
        std::cout << "[VFS] PID:" << event->pid 
                  << " Action:" << (int)event->action 
                  << " Path:" << event->path << std::endl;
        
        // Call the event handler if set
        if (monitor->event_handler_) {
            monitor->event_handler_(*event);
        }
        return 0;
    }
    
    // Debug: Log unexpected sizes occasionally for troubleshooting
    static int debug_counter = 0;
    if (++debug_counter % 1000 == 0) {
        std::cout << "VFS Debug: Received " << debug_counter 
                  << " events with size " << data_sz 
                  << " (expected 4120)" << std::endl;
    }
    
    return 0;
}

} // namespace ebpf